  `method` enum('paypal','nets_qr','wallet') NOT NULL,
  `amount_cents` int NOT NULL,
  `status` enum('PENDING','PAID','REFUND_PENDING','REFUNDED','REFUND_FAILED') NOT NULL DEFAULT 'PENDING',
  `provider_order_id` varchar(64) DEFAULT NULL,
